const icon = (name, extra = '') => `<svg class="icon ${extra}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.grid}"/></svg>`;
const button = (label, action, symbol = '', kind = '', extra = '') => `<button class="btn ${kind}" ${action ? `data-action="${action}"` : ''} ${extra}>${symbol ? icon(symbol) : ''}${label}</button>`;
const linkButton = (label, route, symbol = '', kind = '') => `<a class="btn ${kind}" href="#/${route}">${symbol ? icon(symbol) : ''}${label}</a>`;
const tag = (text, tone = '', symbol = '') => `<span class="tag ${tone}">${symbol ? icon(symbol) : ''}${text}</span>`;
