const segment = (name, options, value) => `<div class="segment" role="group" aria-label="${name}">${options.map(([id,label,symbol]) => `<button data-action="segment" data-group="${name}" data-value="${id}" aria-pressed="${id === value}">${symbol ? icon(symbol) : ''}${label}</button>`).join('')}</div>`;
