const panel = (title, body, extra = '', action = '') => `<section class="panel ${extra}"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`;
const metric = (label, value, foot, symbol, tone = 'blue') => `<article class="panel metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${tone}">${icon(symbol)}</span></div><strong>${value}</strong><small>${foot}</small></article>`;
