const table = (headers, rows, caption = '') => `<div class="table-scroll"><table ${caption ? `aria-label="${caption}"` : ''}><thead><tr>${headers.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const tablePanel = (headers, rows, caption, foot = '') => `<section class="panel flush">${table(headers,rows,caption)}<div class="mobile-rows" aria-label="${caption}">${rows.map(row=>`<article class="mobile-record"><div class="row between"><div class="grow">${row[0]}</div>${headers.at(-1)===''?row.at(-1):''}</div><div class="mobile-record-fields">${row.slice(1,headers.at(-1)===''?-1:undefined).map((cell,i)=>`<div><span>${headers[i+1]}</span><div>${cell}</div></div>`).join('')}</div></article>`).join('')}</div><div class="table-footer"><span>${foot || `${rows.length} รายการ · ข้อมูลตัวอย่าง`}</span><span>แสดงทั้งหมดในช่วงนี้</span></div></section>`;
