function lineChart(series=[42,55,49,72,64,83,68,90,78,101,93,110], labels=months) {
  const width=600,height=225,pad=30,max=Math.max(...series)*1.15;
  const points=series.map((n,i)=>`${pad+i*(width-pad*2)/(series.length-1)},${height-35-n/max*(height-65)}`).join(' ');
  const grid=[0,1,2,3].map(i=>`<line x1="30" x2="580" y1="${25+i*50}" y2="${25+i*50}" class="gridline"/><text x="2" y="${29+i*50}">${Math.round(max*(3-i)/3)}</text>`).join('');
  return `<svg class="chart" viewBox="0 0 600 225" role="img" aria-label="แนวโน้มจำนวนรายการ ${series.join(', ')}"><defs><linearGradient id="chart-fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="currentColor" stop-opacity=".17"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs>${grid}<polygon points="30,190 ${points} 570,190" fill="url(#chart-fade)" style="color:var(--accent)"/><polyline points="${points}" fill="none" class="stroke" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/>${series.map((n,i)=>`<circle cx="${pad+i*(width-pad*2)/(series.length-1)}" cy="${height-35-n/max*(height-65)}" r="3.5" fill="var(--surface-solid)" stroke="var(--accent)" stroke-width="2"/>`).join('')}${labels.map((m,i)=>`<text x="${pad+i*(width-pad*2)/(labels.length-1)}" y="219" text-anchor="middle">${m}</text>`).join('')}</svg>`;
}
