function radar() {
  const cx=180,cy=160,r=95,point=(i,scale)=>[cx+Math.cos(i*Math.PI/4-Math.PI/2)*r*scale,cy+Math.sin(i*Math.PI/4-Math.PI/2)*r*scale];
  return `<svg class="radar" viewBox="0 0 360 325" role="img" aria-label="ความถี่งาน 8 หัวข้อรอง"><g>${[.25,.5,.75,1].map(s=>`<polygon points="${taskNames.map((_,i)=>point(i,s).join(',')).join(' ')}" fill="none" stroke="var(--line)"/>`).join('')}${taskNames.map((n,i)=>{const [x,y]=point(i,1.32);return `<line x1="180" y1="160" x2="${point(i,1)[0]}" y2="${point(i,1)[1]}" stroke="var(--line)"/><text x="${x}" y="${y}" text-anchor="middle">${n}</text>`;}).join('')}<polygon points="${[.9,.72,.58,.81,.68,.41,.54,.35].map((s,i)=>point(i,s).join(',')).join(' ')}" fill="var(--blue)" fill-opacity=".7" stroke="var(--accent)" stroke-width="2"/></g></svg>`;
}
