function reviewControls() { showSheet('ตัวเลือกตรวจแบบ','เปลี่ยนเฉพาะต้นแบบ ไม่กระทบระบบที่ใช้งานอยู่',`<div class="stack">${field('หน้าจอ',select('review-route',routes.map(r=>[r[0],r[1]]),state.route))}${field('สถานะข้อมูล',select('review-state',[['normal','ปกติ'],['loading','กำลังโหลด'],['empty','ไม่มีข้อมูล'],['error','โหลดล้มเหลว'],['offline','ออฟไลน์']],state.view))}${field('บทบาทตัวอย่าง',select('review-role',[['staff','Staff'],['admin','Admin'],['superadmin','Superadmin']],state.role))}${linkButton('ชุด UI และสถานะ','design','grid','glass')}</div>`); }
function downloadCSV() {
  const csv='\ufeff'+[['วันที่','เวลา','เจ้าหน้าที่','หัวข้อรอง'],...exportRows().map(l=>[l.date,l.time,l.person,l.task])].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`DEMO-worklogs-fy${state.year}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeSheet();toast('ดาวน์โหลด CSV ตัวอย่างแล้ว');
}
function exportRows(){
  const start=`${fiscalStart()}-10-01`,end=`${fiscalStart()+1}-09-30`;
  const selected=state.exportSelection||{scope:'all',person:'all'};
  return state.logs.filter(log=>log.date>=start&&log.date<=end&&(selected.scope!=='self'||log.person===people[0].name)&&(selected.person==='all'||log.person===people.find(p=>p.id===selected.person)?.name));
}
