  'preview-broadcast':()=>{const f=$('#broadcast-form');if(!f.reportValidity())return;const v=new FormData(f);showSheet('ตรวจประกาศก่อนส่ง',v.get('audience'),`<h3>${escapeHTML(v.get('title'))}</h3><p style="margin:15px 0">${escapeHTML(v.get('message'))}</p>${note('การยืนยันในต้นแบบแสดงผลจำลอง ไม่ส่งหาผู้ใช้จริง','amber','bell')}`,button('ยืนยันตัวอย่างประกาศ','confirm-broadcast','send','primary'));},
